1839	    const freed = [];
1840	    for (const node of due) {
1841	      const lease = leases.get(node.token);
1842	      // The global reclaim is committed. Usage was projected out of every
1843	      // owner before the write, so here the share is only forgotten from
1844	      // retired sets and the table; no owner moves usage a second time.
1845	      purgeRetired(lease);
