12	// Run one registry operation in a fresh OS process, so its per-process
13	// registry identity restarts exactly as in a real crash recovery.
14	function childRun(mode, p) {
15	  const body = `
16	    import { createRegistry } from ${JSON.stringify(`file://${REGISTRY_SRC}`)};
17	    const [mode, p] = process.argv.slice(1);
18	    const r = createRegistry({ ttlMs: 100, clock: () => 0, logPath: p });
19	    if (mode === 'setup') {
20	      const tokens = [r.acquire('a', 'h').token];
21	      const dead = r.acquire('freed', 'h');
22	      tokens.push(dead.token);
23	      r.release(dead.token);
24	      for (const l of r.acquireAll(['x', 'x'], 'h', 10)) tokens.push(l.token);
25	      r.compact();
26	      process.stdout.write(JSON.stringify(tokens));
27	    } else {
28	      process.stdout.write(r.acquire('new', 'h').token);
29	    }
30	  `;
31	  return execFileSync(
32	    process.execPath,
33	    ['--input-type=module', '-e', body, mode, p],
34	    { encoding: 'utf8' },
35	  );
36	}
