38	function fakeClock(start = 0) {
39	  let now = start;
40	  const clock = () => now;
41	  clock.set = (value) => {
42	    now = value;
43	  };
44	  clock.advance = (delta) => {
45	    now += delta;
46	  };
47	  return clock;
48	}
