// Read-only self-check. It recomputes every invariant from the raw tables
// instead of trusting the lazily maintained owner figures, reports what it
// found and never repairs anything or throws on an internal discrepancy.
// Like exportState it judges liveness against `now` alone and neither
// reclaims nor wakes nor times anything out.
function checkConsistency(now = clock()) {
  if (!Number.isFinite(now)) {
    throw new TypeError('now must be a finite number');
  }

  const issues = [];
  const issue = (kind, subject, expected, actual) => {
    issues.push({ kind, subject, expected, actual });
  };

  // --- Leases: token table, slots and live credential epochs.
  let liveCount = 0;
  const liveByResource = new Map();
  const liveByQuota = new Map();
  const liveEpochsByResource = new Map();
  for (const [token, lease] of leases.entries()) {
    if (typeof token !== 'string' || token === '') {
      issue('lease:token-key', String(token), 'non-empty string', token);
    }
    const set = slots.get(lease.resource);
    if (set === undefined || !set.has(token)) {
      issue('lease:slot-missing', token, true, false);
    }
    const rs = resourceStates.get(lease.resource);
    if (rs === undefined) {
      issue('lease:resource-missing', token, lease.resource, null);
    } else if (!rs.declared) {
      // An exclusive resource carries at most one live credential.
      const count = liveByResource.get(lease.resource) ?? 0;
      if (isLive(lease, now) && count > 0) {
        issue(
          'resource:capacity',
          lease.resource,
          1,
          count + 1,
        );
      }
    }
    if (!Number.isInteger(lease.epoch) || lease.epoch <= 0) {
      issue('lease:epoch', token, 'positive integer', lease.epoch);
    } else {
      let seen = liveEpochsByResource.get(lease.resource);
      if (seen === undefined) {
        seen = new Set();
        liveEpochsByResource.set(lease.resource, seen);
      }
      if (isLive(lease, now)) {
        if (seen.has(lease.epoch)) {
          issue(
            'lease:epoch-unique',
            `${String(lease.resource)}#${lease.epoch}`,
            1,
            2,
          );
        }
        seen.add(lease.epoch);
      }
    }
    if (isLive(lease, now)) {
      liveCount += 1;
      liveByResource.set(
        lease.resource,
        (liveByResource.get(lease.resource) ?? 0) + 1,
      );
      for (const quota of lease.chain) {
        liveByQuota.set(quota, (liveByQuota.get(quota) ?? 0) + 1);
      }
    }
  }
