  // slot/table bijection is checked per lease above).
  for (const [resource, set] of slots.entries()) {
    for (const token of set) {
      if (!leases.has(token)) {
        issue('slot:lease-missing', token, true, false);
      }
      const lease = leases.get(token);
      if (lease !== undefined && lease.resource !== resource) {
        issue(
          'slot:resource',
          token,
          resource,
          lease.resource,
        );
      }
    }
