import { createRegistry } from './src/index.js';

let t = 0;
const clock = () => t;
const r = createRegistry({ ttlMs: 100, clock });

// empty
console.log('empty export:', JSON.stringify(r.exportState(0)));
console.log('empty check:', JSON.stringify(r.checkConsistency(0)));

r.setQuota('root', 2);
r.setQuota('east', 2, 'root');
r.declareResource('pool', 2, 'east');
const a = r.acquire('pool', 'h1', 50);
const b = r.acquire('solo', 'h2', 100);
