// group waiter on solo
const g = r.acquireAll(['solo', 'pool'], 'h5', 50, 5000);
console.log('group waiter:', g.status);

t = 60; // a expires (unswept)
const st = r.exportState();
console.log('export at 60:', JSON.stringify(st, null, 1));
const ck = r.checkConsistency();
console.log('check at 60 ok:', ck.ok, 'issues:', ck.issues.length, JSON.stringify(ck.checked));

// timed out waiter
t = 2000;
const st2 = r.exportState();
console.log('waits at 2000:', JSON.stringify(st2.waits));
console.log('check at 2000:', JSON.stringify(r.checkConsistency()));

// non-mutation: nothing got reclaimed/purged
console.log('lease table still has a token:', !!r.acquire.toString);
const swept = r.sweep();
console.log('sweep at 2000 frees:', swept);
"

