2105	  // gone, and a lazy observation at a different reading is left for the next
2106	  // mutating call rather than reported as corruption.
2107	  function checkConsistency(now = clock()) {
2108	    if (!Number.isFinite(now)) {
2109	      throw new TypeError('now must be a finite number');
2110	    }
2111	
2112	    const issues = [];
2113	    const issue = (kind, subject, expected, actual) => {
2114	      issues.push({ kind, subject, expected, actual });
2115	    };
2116	
2117	    // A share an owner has observed expire (and so no longer counts) is one
2118	    // whose token sits in the owner's retired set with a matching heap
2119	    // sequence. A record with a stale sequence describes a renewed lease and
2120	    // is treated as absent, the way the next reconcile would.
2121	    const ownerCountsShare = (owner, token, lease) => {
2122	      const record = owner.retired.get(token);
2123	      return record === undefined || record.heapSeq !== lease.heapSeq;
2124	    };
2125	
2126	    // Every lease still in the table must be reachable on the global expiry
2127	    // heap (so a sweep can reclaim it), on its resource heap, and on every
2128	    // quota heap of its chain (so lazy reconciliation can observe it). A
2129	    // renewed lease keeps its old stale nodes but always has one current
2130	    // node carrying the latest heap sequence; a structurally superseded
2131	    // lease is deleted from the table together with its nodes.
2132	    const heapHasCurrentNode = (heap, token, heapSeq) => {
2133	      for (const node of heap.nodes) {
2134	        if (node.token === token && node.heapSeq === heapSeq) {
2135	          return true;
2136	        }
2137	      }
2138	      return false;
2139	    };
2140	
2141	    // --- Leases and slots: the lease table is the authority, the per-
2142	    //     resource slot sets must mirror it exactly, epochs stay unique per
2143	    //     resource and below the high-water mark.
2144	    const epochSeenByResource = new Map();
2145	    for (const [token, lease] of leases.entries()) {
2146	      if (typeof token !== 'string' || token === '') {
2147	        issue('lease:token-key', keyOf(token), 'non-empty string', token);
2148	      }
2149	      if (!knownTokens.has(token)) {
2150	        issue('lease:known-token', token, true, false);
2151	      }
2152	      if (lease.resource === null || lease.resource === undefined) {
2153	        issue('lease:resource', token, 'named resource', lease.resource);
2154	      }
2155	      const set = slots.get(lease.resource);
2156	      if (set === undefined || !set.has(token)) {
2157	        issue('lease:slot-missing', token, true, false);
2158	      }
2159	      // The global heap is only ever popped by a sweep, which deletes the
2160	      // lease in the same commit, so every table lease has its current node.
2161	      if (!heapHasCurrentNode(expiryQueue, token, lease.heapSeq)) {
2162	        issue('lease:global-heap', token, true, false);
2163	      }
2164	      if (!Number.isFinite(lease.expiresAt) || !Number.isFinite(lease.ttlMs)) {
2165	        issue('lease:expiry', token, 'finite numbers', {
2166	          expiresAt: lease.expiresAt,
2167	          ttlMs: lease.ttlMs,
2168	        });
2169	      }
2170	      if (!Number.isInteger(lease.epoch) || lease.epoch <= 0) {
2171	        issue('lease:epoch', token, 'positive integer', lease.epoch);
2172	      } else {
2173	        let seen = epochSeenByResource.get(lease.resource);
2174	        if (seen === undefined) {
2175	          seen = new Set();
2176	          epochSeenByResource.set(lease.resource, seen);
2177	        }
2178	        // Committed credential epochs advance by exactly one, so two
2179	        // credentials of one resource can never share an epoch, including a
2180	        // live credential next to an expired, unreclaimed older one.
2181	        if (seen.has(lease.epoch)) {
2182	          issue(
2183	            'lease:epoch-unique',
2184	            `${keyOf(lease.resource)}#${lease.epoch}`,
2185	            1,
2186	            2,
2187	          );
2188	        }
2189	        seen.add(lease.epoch);
2190	        const high = epochs.get(lease.resource);
2191	        if (high === undefined || lease.epoch > high) {
2192	          issue('epoch:high-water', keyOf(lease.resource), high ?? 0, lease.epoch);
2193	        }
2194	      }
2195	    }
2196	    for (const [resource, set] of slots.entries()) {
2197	      for (const token of set) {
