    for (const token of set) {
      const lease = leases.get(token);
      if (lease === undefined) {
        issue('slot:lease-missing', token, true, false);
      } else if (lease.resource !== resource) {
        issue('slot:resource', token, keyOf(resource), keyOf(lease.resource));
      }
    }
  }
